rets.GH_PAGES_DEPLOY_KEY }} external_repository: 9router/9router.github.io publish_branch: main publish_dir: gitbook/out force_orphan: true user_name: github-actions[bot] user_email: github-actions[bot]@users.noreply.github.com commit_message: "deploy: ${{ github.sha }}"name: Tests on: push: branches: [main, master] pull_request: concurrency: group: tests cancel-in-progress: true jobs: test: runs-on: ubuntu-latest steps: - uses: actions/checkout@v5 - uses: oven-sh/setup-bun@v2 with: bun-version: 1.4.2 - uses: actions/setup-node@v6 with: node-version: 24 - name: Install root deps run: bun install --frozen-lockfile - name: Install test deps working-directory: tests run: bun install --frozen-lockfile - name: Run test suite working-directory: tests run: bunx vitest run --reporter=json --outputFile=results.json - name: Verify no regression vs baseline run: node tests/__baseline__/verify-no-regression.mjs tests/results.jsonversion: 2 updates: []# Memory Maintenance
## Discovery Model
- Core principle: progressive discovery through references, building a graph of memories. - Initially, agents are provided with the list of all memories (names only). - Agents should read `mem:core` as the top-level entry point (graph root). This memory should contain references to other memories covering major project domains. The referenced memories shall, in turn, shall contain references to even more specific memories, and so on. The depth of the graph shall depend on the project complexity. - Use topics/folders to group related memories in order to make the content structure explicit. Folders can mirror project structure (e.g. modules like frontend/backend) or topics like debugging, architecture, etc. - Memory references must use a mem: prefix inside backticks, e.g. `mem:frontend/core`. The surrounding text should clearly indicate when to read the memory/which content to expect. The text should provide more precise guidance than the memory name alone, i.e. avoid a reference like "frontend debugging: `mem:frontend/debugging` and instead make clear which aspects of frontend debugging are covered. - Memories themselves should not contain information about when to read them; this is the responsibility of the referring memory.
## Style
Dense agent notes, not prose docs. Prefer invariants, terse bullets. Avoid obvious context, rationale, and examples unless they prevent likely mistakes. Keep guidance durable and generalizable, not task-local.
## Add/update threshold
Add or update memories only with stable, non-obvious project conventions that avoid complex rediscovery in the future. Do not add: quick-read facts; generic language/framework knowledge; one-off task notes; volatile line-level details; behavior likely to change soon.
## Maintenance Actions
- Renaming memories: References are updated automatically if handled via Serena's memory rename tool. - Checking for stale memories (e.g. after deletion): Call `serena memories check` for a report./cache /project.local.ymlproject_name: "9router" language_servers: - typescript encoding: "utf-8" activation_command: activation_command_timeout: 180.0 line_ending: language_backend: ignore_all_files_in_gitignore: true ls_specific_settings: {} ls_workspace_folders: - "." ls_additional_workspace_folders: [] ignored_paths: [] read_only: false excluded_tools: [] included_optional_tools: [] fixed_tools: [] default_modes: added_modes: initial_prompt: "" symbol_info_budget: read_only_memory_patterns: [] ignored_memory_patterns: [] included_apis: [] excluded_apis: [] agent_interface:function getDataDir() ⋮---- function getRuntimeDir() ⋮---- function getRuntimeNodeModules() ⋮---- function ensureRuntimeDir() ⋮---- function hasModule(name) ⋮---- function isGlibcRuntime() ⋮---- function getBetterSqliteBinary() ⋮---- function isBetterSqliteBinaryValid() ⋮---- function summarizeNpmError(stderr = "") ⋮---- function runNpmInstall( ⋮---- function npmInstall(pkgs, opts = ⋮---- function isSqlJsWasmValid() ⋮---- function ensureSqliteRuntime( ⋮---- function buildEnvWithRuntime(baseEnv = process.env)function hasSystray() ⋮---- function cleanupLegacySystray( ⋮---- function chmodSystrayBin( ⋮---- function ensureRuntimeDir() ⋮---- function npmInstall(pkgs, ⋮---- function ensureTrayRuntime(function shouldExclude(name) ⋮---- function copyRecursive(src, dest) ⋮---- function resolveStandaloneBuild(appDir, buildDistDir) ⋮---- function copyStandaloneBuild(appDir, buildDistDir, cliAppDir) ⋮---- function mergeServerArtifacts(buildDistDir, cliAppDir) ⋮---- function assertRequiredApiArtifacts(cliAppDir) ⋮---- function buildCliPackage() ⋮---- function ensureModuleInBundle(pkg) ⋮---- // Step 4: Copy static filesasync function buildEntry(entry) ⋮---- setup(build) ⋮---- async function run()function getDataDir(