5 0 1 1-1.5 0 .75.75 0 0 1 1.5 0m1.75.75a.75.75 0 1 0 0-1.5.75.75 0 0 0 0 1.5" fill="#666"/></svg>export function copyStandaloneAssets(.replace(/^const RISK_NOTICE\s*=.*$/m, ""); // remove redeclaration // eslint-disable-next-line no-new-func ⋮---- // Extra fields cần lấy từ providers.js (không lấy display, id, alias vì đã có nguồn khác) ⋮---- // Extract uiAlias từ alias: "xxx" ⋮---- // thinkingConfig ⋮---- // authType (webCookie) ⋮---- // regions (xiaomi-tokenplan) ⋮---- // ── 3. Inject vào từng registry file ── ⋮---- // Thay RISK_NOTICE string về const reference khi serialize ⋮---- // Build uiAlias line (chỉ khi khác với alias routing) ⋮---- // Build extra fields ⋮---- // Inject SAU dòng "alias:" hoặc cuối object (trước closing "};") ⋮---- // Tìm vị trí sau field "alias:" để injectfunction migrateEntry(entry, filename) ⋮---- function formatValue(v, indent = 0) ⋮---- function formatInlineObject(obj) ⋮---- function formatConfig(cfg) ⋮---- function formatEntry(entry, imports = "") ⋮---- function emitKey(k)function memberFromModel(model) ⋮---- async function send(label, content, extra = ⋮---- async function showCaps() ⋮---- } catch { /* ignore */ } ⋮---- // 1. Text-only: round-robin order (no capability requirement).async function translateToLanguage(readmeContent, targetLang) ⋮---- async function main()# 9Router — Agent Skills
Drop-in skills for any AI agent (Claude, Cursor, ChatGPT, custom SDK). Just **copy a link** below and paste it to your AI — it will fetch the skill and use 9Router for you.
> Tip: start with the **9router** entry skill — it covers setup and links to all capability skills.
## Skills
